def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r])]
    sep_cols = [c for c in range(w) if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h))]

    def bands(n, seps):
        edges = [-1] + seps + [n]
        return [(edges[i] + 1, edges[i + 1]) for i in range(len(edges) - 1)]

    rbands = bands(h, sep_rows)
    cbands = bands(w, sep_cols)
    out = [row[:] for row in grid]

    # Learn the adjacent compartment pairing for each object color from
    # row-bands where both sides of a reflected pair are present.
    pair_for_color = {}
    for r0, r1 in rbands:
        for j in range(len(cbands) - 1):
            a0, a1 = cbands[j]
            b0, b1 = cbands[j + 1]
            if a1 - a0 != b1 - b0:
                continue
            colors_a = {grid[r][c] for r in range(r0, r1) for c in range(a0, a1) if grid[r][c]}
            colors_b = {grid[r][c] for r in range(r0, r1) for c in range(b0, b1) if grid[r][c]}
            for color in colors_a & colors_b:
                pair_for_color.setdefault(color, (j, j + 1))

    # For a lone compartment object of a color, complete its learned reflected pair.
    for r0, r1 in rbands:
        for j, (c0, c1) in enumerate(cbands):
            colors = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c]}
            for color in colors:
                pair = pair_for_color.get(color)
                if pair is None or j not in pair:
                    continue
                other = pair[1] if j == pair[0] else pair[0]
                d0, d1 = cbands[other]
                if any(grid[r][c] != 0 for r in range(r0, r1) for c in range(d0, d1)):
                    continue
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        if grid[r][c] == color:
                            dest_c = d0 + (c1 - 1 - c if other > j else c0 + c1 - 1 - c - d0)
                            # Equivalent reflection of the local column index.
                            dest_c = d0 + (c1 - 1 - c)
                            if d0 <= dest_c < d1:
                                out[r][dest_c] = color

    return out
